  [MenuItem("Truck Sports/Pedestrian Plowing/Refresh Crowd Rendering")]public static void Install(){PlowBadgesAuthoring.Install();PlowCharacterPolish.Install();foreach(var path in new[]{PlowAuthoring.Scene,PlowCabAuthoring.Scene}){var scene=EditorSceneManager.OpenScene(path);var m=UnityEngine.Object.FindAnyObjectByType<PlowMatch>();foreach(var entry in m.crowdSettings.characters){if(entry.reactions!=null)continue;string id=entry.prefab.name.Replace(" Parade","");var profile=AssetDatabase.LoadAssetAtPath<LWS.TruckTaxi.PassengerProfile>("Assets/LWS/TruckTaxi/Passengers/Profiles/"+id+".asset");if(profile!=null)entry.reactions=profile.authoredDialogue;}EditorUtility.SetDirty(m.crowdSettings);
    foreach(string name in new[]{"Festival canopy","Festival pennant"}){var mesh=AssetDatabase.LoadAssetAtPath<Mesh>(PlowAuthoring.Root+"/Models/"+name+".asset");mesh.normals=Enumerable.Repeat(name.Contains("canopy")?Vector3.up:Vector3.back,mesh.vertexCount).ToArray();EditorUtility.SetDirty(mesh);}
    var fire=AssetDatabase.LoadAssetAtPath<Material>(PlowAuthoring.Root+"/Materials/Parade fire.mat");fire.SetTexture("_BaseMap",AssetDatabase.LoadAssetAtPath<Texture2D>("Assets/CoreCollapse/Textures/muzzle_05_rotated.png"));fire.SetFloat("_Surface",1);fire.SetFloat("_Blend",2);fire.SetFloat("_SrcBlend",5);fire.SetFloat("_DstBlend",1);fire.SetFloat("_DstBlendAlpha",1);fire.EnableKeyword("_SURFACE_TYPE_TRANSPARENT");fire.SetFloat("_ZWrite",0);fire.renderQueue=3000;EditorUtility.SetDirty(fire);
    foreach(var p in m.props)if(p.breakable==null)Breakable(p);
    if(m.hitDust==null||m.hitDust.Length==0){m.hitDust=new ParticleSystem[8];var prefab=AssetDatabase.LoadAssetAtPath<GameObject>("Assets/CoreCollapse/Demo/Prefabs/Particles/Dust.prefab");for(int i=0;i<8;i++){var g=UnityEngine.Object.Instantiate(prefab,m.transform);g.name="Pooled Core-Collapse impact dust "+i;foreach(var b in g.GetComponentsInChildren<MonoBehaviour>(true))UnityEngine.Object.DestroyImmediate(b);var dust=g.GetComponentInChildren<ParticleSystem>();dust.Stop(true,ParticleSystemStopBehavior.StopEmittingAndClear);var main=dust.main;main.playOnAwake=false;main.loop=false;main.maxParticles=32;main.startLifetime=new ParticleSystem.MinMaxCurve(.2f,.6f);main.startSize=new ParticleSystem.MinMaxCurve(.3f,.8f);main.startSpeed=new ParticleSystem.MinMaxCurve(.4f,2);main.simulationSpace=ParticleSystemSimulationSpace.World;var emission=dust.emission;emission.rateOverTime=0;emission.SetBursts(new[]{new ParticleSystem.Burst(0,16)});m.hitDust[i]=dust;}}
