    m.hud.summaryBackings=new RectTransform[4];for(int i=0;i<4;i++){var backing=m.menus.viewPanels[i].Find("View data backing")??m.menus.viewPanels[i].Find("Parade card backing");backing.name="Parade card backing";m.hud.summaryBackings[i]=backing.GetComponent<RectTransform>();m.hud.summary[i].rectTransform.sizeDelta=new Vector2(478,126);m.hud.summary[i].fontSizeMax=20;m.hud.summary[i].fontSizeMin=17;m.hud.summaryBackings[i].sizeDelta=new Vector2(500,140);}
