  static void Breakable(PlowProp prop){var p=prop.gameObject;var support=p.AddComponent<Support>();var s=new SerializedObject(support);s.FindProperty("supportedBy").arraySize=0;s.ApplyModifiedPropertiesWithoutUndo();typeof(Support).GetField("onCollapse",BindingFlags.Instance|BindingFlags.NonPublic).SetValue(support,new Support.OnCollapseEvent());EditorUtility.SetDirty(support);var c=p.AddComponent<PlowBreakable>();c.intactBody=prop.body;c.model=p.transform.Find("Owned model meshes");var so=new SerializedObject(c);so.FindProperty("startingHp").floatValue=20;so.ApplyModifiedPropertiesWithoutUndo();c.fragments=new Rigidbody[2];
   var vendor=AssetDatabase.LoadAssetAtPath<GameObject>("Assets/CoreCollapse/Demo/Prefabs/PreFrag/Wall-Frag.prefab");var source=vendor.GetComponentsInChildren<MeshFilter>();Bounds bounds=source[0].GetComponent<Renderer>().bounds;foreach(var f in source)bounds.Encapsulate(f.GetComponent<Renderer>().bounds);var material=c.model.GetComponentInChildren<Renderer>().sharedMaterial;
   for(int side=0;side<2;side++){var half=new GameObject("Pooled Core-Collapse fracture half "+side);half.transform.SetParent(p.transform,false);half.layer=2;foreach(var f in source){if((f.GetComponent<Renderer>().bounds.center.x<bounds.center.x?0:1)!=side)continue;var part=new GameObject(f.name);part.layer=2;part.transform.SetParent(half.transform,false);part.transform.localPosition=Vector3.Scale(f.transform.position-bounds.center,new Vector3(1.1f/bounds.size.x,1.2f/bounds.size.y,1.1f/bounds.size.z))+Vector3.up*.6f;part.transform.localRotation=f.transform.rotation;part.transform.localScale=Vector3.Scale(f.transform.lossyScale,new Vector3(1.1f/bounds.size.x,1.2f/bounds.size.y,1.1f/bounds.size.z));part.AddComponent<MeshFilter>().sharedMesh=f.sharedMesh;part.AddComponent<MeshRenderer>().sharedMaterial=material;}var body=half.AddComponent<Rigidbody>();body.mass=1;body.maxLinearVelocity=14;body.maxAngularVelocity=7;body.linearDamping=.5f;body.angularDamping=.6f;var shape=half.AddComponent<BoxCollider>();shape.center=new Vector3(side==0?-.275f:.275f,.6f,0);shape.size=new Vector3(.54f,1.2f,1.1f);c.fragments[side]=body;half.SetActive(false);}
   prop.breakable=c;EditorUtility.SetDirty(c);EditorUtility.SetDirty(prop);
  }
 }
